THE KEEP (commit 11e1ff440), verbatim. Helper defined immediately before damage_enemy:

    static inline f32 scale_fight_damage(f32 fight, f32 health, f32 upper,
                                         f32 lower, s32 type)
    {
        if (health > upper) {
            goto done;
        }
        if (type == E_DEATH) {
            return fight;
        }
        if (health > lower) {
            return (f32)(lbl_80346A30 * fight);
        }
        return (f32)(lbl_80346A28 * fight);
    done:
        return fight;
    }

